BEGIN;
DO $$BEGIN IF encode(extensions.digest((SELECT prosrc FROM pg_proc WHERE oid='public.sandy_tenant_lifecycle_operation_config(text)'::regprocedure),'sha256'),'hex') IS DISTINCT FROM '4831ccf518280d8ce5131a8a5262f348beb7bc35171d6936091dbf921a4b40da' THEN RAISE EXCEPTION 'financial_redaction_prior_dispatch_changed';END IF;END $$;
CREATE OR REPLACE FUNCTION public.sandy_tenant_lifecycle_operation_config(p_operation text) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
 SELECT $config${"supabase.tenant.export":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"export"},"supabase.tenant.manifests.export":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"export"},"supabase.tenant.erase":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"erase"},"supabase.tenant.manifests.erase":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"erase"},"supabase.tenant.restore":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"restore"},"supabase.tenant.manifests.restore":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"restore"},"supabase.tenant.exports.get":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"get"},"supabase.tenant.manifests.exports.get":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"get"},"supabase.tenant.exports.purge":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"purge"},"supabase.tenant.manifests.exports.purge":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"purge"},"supabase.tenant.protected_resources.inventory":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"inventory"},"supabase.tenant.content.export":{"manifest":"customer_content_fragments_v1","scope_sha256":"f03c397e8c2ba3276d669cab643832a891899f6529274da2de1d6b52fd99c1ad","action":"content_export"},"supabase.tenant.content.exports.get":{"manifest":"customer_content_fragments_v1","scope_sha256":"f03c397e8c2ba3276d669cab643832a891899f6529274da2de1d6b52fd99c1ad","action":"content_get"},"supabase.tenant.content.exports.purge":{"manifest":"customer_content_fragments_v1","scope_sha256":"f03c397e8c2ba3276d669cab643832a891899f6529274da2de1d6b52fd99c1ad","action":"purge"},"supabase.tenant.support.snapshot":{"manifest":"support_case_recovery_v1","scope_sha256":"c691594174ef0f5b74c1c815568dab535a74a1b2f05f8a187bda3f41da1709b7","action":"export"},"supabase.tenant.support.erase":{"manifest":"support_case_recovery_v1","scope_sha256":"c691594174ef0f5b74c1c815568dab535a74a1b2f05f8a187bda3f41da1709b7","action":"erase"},"supabase.tenant.support.restore":{"manifest":"support_case_recovery_v1","scope_sha256":"c691594174ef0f5b74c1c815568dab535a74a1b2f05f8a187bda3f41da1709b7","action":"restore"},"supabase.tenant.support.snapshots.get":{"manifest":"support_case_recovery_v1","scope_sha256":"c691594174ef0f5b74c1c815568dab535a74a1b2f05f8a187bda3f41da1709b7","action":"get"},"supabase.tenant.support.snapshots.purge":{"manifest":"support_case_recovery_v1","scope_sha256":"c691594174ef0f5b74c1c815568dab535a74a1b2f05f8a187bda3f41da1709b7","action":"purge"},"supabase.tenant.financial.export":{"manifest":"customer_financial_fragments_v1","scope_sha256":"bceaaef0ff9b597918fc55ac9658db0b928eaa85739a4ef8435fa7ca10a9085d","action":"content_export"},"supabase.tenant.financial.exports.get":{"manifest":"customer_financial_fragments_v1","scope_sha256":"bceaaef0ff9b597918fc55ac9658db0b928eaa85739a4ef8435fa7ca10a9085d","action":"content_get"},"supabase.tenant.financial.exports.purge":{"manifest":"customer_financial_fragments_v1","scope_sha256":"bceaaef0ff9b597918fc55ac9658db0b928eaa85739a4ef8435fa7ca10a9085d","action":"purge"},"supabase.tenant.financial.redaction.policies.create":{"manifest":"financial_subject_text_redaction_v1","scope_sha256":"b686b66a7f00b944a9aca973b3cc1e7d2d5e322b429246006d9662da011e17c8","action":"policy_control"},"supabase.tenant.financial.redaction.policies.get":{"manifest":"financial_subject_text_redaction_v1","scope_sha256":"b686b66a7f00b944a9aca973b3cc1e7d2d5e322b429246006d9662da011e17c8","action":"policy_control"},"supabase.tenant.financial.redaction.policies.revoke":{"manifest":"financial_subject_text_redaction_v1","scope_sha256":"b686b66a7f00b944a9aca973b3cc1e7d2d5e322b429246006d9662da011e17c8","action":"policy_control"},"supabase.tenant.financial.redaction.preview":{"manifest":"financial_subject_text_redaction_v1","scope_sha256":"b686b66a7f00b944a9aca973b3cc1e7d2d5e322b429246006d9662da011e17c8","action":"policy_control"},"supabase.tenant.financial.redaction.apply":{"manifest":"financial_subject_text_redaction_v1","scope_sha256":"b686b66a7f00b944a9aca973b3cc1e7d2d5e322b429246006d9662da011e17c8","action":"erase"}}$config$::jsonb->p_operation
$$;
DO $$BEGIN IF encode(extensions.digest((SELECT prosrc FROM pg_proc WHERE oid='public.sandy_tenant_manifest_resolve(text)'::regprocedure),'sha256'),'hex') IS DISTINCT FROM '1c125d63c638355c7f6fe09844331286af821487982207baec12ba77c38a6f0c' THEN RAISE EXCEPTION 'financial_redaction_prior_dispatch_changed';END IF;END $$;
CREATE OR REPLACE FUNCTION public.sandy_tenant_manifest_resolve(p_manifest text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF p_manifest='application_leaf_links_v1' THEN RETURN public.sandy_tenant_manifest_v1();
 ELSIF p_manifest='application_scalar_links_v1' THEN RETURN public.sandy_tenant_manifest_scalar_v1();
 ELSIF p_manifest='customer_content_fragments_v1' THEN RETURN public.sandy_tenant_content_manifest_v1();
 ELSIF p_manifest='support_case_recovery_v1' THEN RETURN public.sandy_tenant_support_manifest_v1();
 ELSIF p_manifest='customer_financial_fragments_v1' THEN RETURN public.sandy_tenant_financial_manifest_v1();
 ELSIF p_manifest='financial_subject_text_redaction_v1' THEN RETURN public.sandy_tenant_financial_redaction_manifest_v1();
 ELSE RAISE EXCEPTION 'tenant_manifest_not_supported';END IF;
END $$;
CREATE FUNCTION public.sandy_tenant_financial_redaction_metadata(p_policy public.sandy_tenant_financial_redaction_policies) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS $$
 SELECT jsonb_build_object('policy_id',(p_policy).id,'tenant_id',(p_policy).tenant_id,'manifest','financial_subject_text_redaction_v1','manifest_sha256',(p_policy).manifest_sha256,'schema_sha256',(p_policy).schema_sha256,'resource',(p_policy).resource,'record_count',cardinality((p_policy).record_ids),'source_sha256',(p_policy).source_sha256,'consent_revision',(p_policy).consent_revision,'source_cutoff',(p_policy).source_cutoff,'effective_at',(p_policy).effective_at,'expires_at',(p_policy).expires_at,'basis',(p_policy).basis,'policy_reference',(p_policy).policy_reference,'policy_reference_verified',false,'created_at',(p_policy).created_at,'state',CASE WHEN EXISTS(SELECT 1 FROM public.sandy_tenant_financial_redaction_revocations WHERE policy_id=(p_policy).id) THEN 'revoked' WHEN EXISTS(SELECT 1 FROM public.sandy_tenant_financial_redaction_applications WHERE policy_id=(p_policy).id) THEN 'applied' WHEN (p_policy).consent_revision IS DISTINCT FROM(SELECT revision FROM public.sandy_supabase_tenant_consents WHERE tenant_id=(p_policy).tenant_id) THEN 'invalidated' WHEN (p_policy).expires_at<=clock_timestamp() THEN 'expired' WHEN (p_policy).effective_at>clock_timestamp() THEN 'not_effective' ELSE 'active' END,'redacted_fields',(SELECT value->'redacted_fields' FROM jsonb_array_elements(public.sandy_tenant_financial_redaction_manifest_v1()->'resources') WHERE value->>'table'=(p_policy).resource),'retained_categories',public.sandy_tenant_financial_redaction_manifest_v1()->'retained_categories','complete_tenant_coverage',false,'financial_records_preserved',true,'external_provider_assets_included',false,'retained_control_copies',true,'restore_supported',false)
$$;
CREATE FUNCTION public.sandy_tenant_financial_redaction_execute(p_actor uuid,p_admission uuid,p_canonical text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS $$
DECLARE ctx jsonb;args jsonb;tenant uuid;op text;policy public.sandy_tenant_financial_redaction_policies;consent public.sandy_supabase_tenant_consents;controls public.sandy_supabase_tenant_controls;manifest jsonb:=public.sandy_tenant_financial_redaction_manifest_v1();plan jsonb;after_plan jsonb;result jsonb;previous jsonb;ids uuid[];resource text;cutoff timestamptz;effective timestamptz;expiry timestamptz;before_sha text;after_sha text;row jsonb;affected integer;changed integer:=0;current_valid boolean;hold_blocked boolean;sets text;projection text;actual_sha text;col jsonb;entry jsonb;
BEGIN
 ctx:=public.sandy_tenant_lifecycle_context(p_actor,p_admission,p_canonical);args:=ctx->'arguments';tenant:=(ctx->>'tenant_id')::uuid;op:=ctx->>'operation';
 IF op NOT IN('supabase.tenant.financial.redaction.policies.create','supabase.tenant.financial.redaction.policies.get','supabase.tenant.financial.redaction.policies.revoke','supabase.tenant.financial.redaction.preview','supabase.tenant.financial.redaction.apply') OR ctx->>'manifest' IS DISTINCT FROM manifest->>'id' THEN RAISE EXCEPTION 'financial_redaction_operation_not_supported';END IF;
 SELECT receipt.result INTO previous FROM public.sandy_tenant_financial_redaction_receipts receipt WHERE receipt.admission_id=p_admission;
 IF FOUND THEN RETURN jsonb_build_object('ok',true,'result',previous,'reused',true);END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('tenant_financial_redaction:'||tenant::text,0));
 SELECT * INTO consent FROM public.sandy_supabase_tenant_consents WHERE tenant_id=tenant FOR SHARE;
 SELECT * INTO controls FROM public.sandy_supabase_tenant_controls WHERE tenant_id=tenant FOR SHARE;
 IF public.sandy_tenant_financial_redaction_schema_sha256() IS DISTINCT FROM manifest->>'schema_sha256' THEN RAISE EXCEPTION 'financial_redaction_schema_changed';END IF;
 IF op='supabase.tenant.financial.redaction.policies.create' THEN
  IF consent.allow_erasure IS DISTINCT FROM true OR args->>'acknowledge_retained_financial_records' IS DISTINCT FROM 'true' OR args->>'acknowledge_retained_control_copies' IS DISTINCT FROM 'true' OR args->>'basis' NOT IN('subject_data_request','approved_retention_schedule') OR args->>'policy_reference' IS NULL OR jsonb_typeof(args->'record_ids') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'financial_redaction_explicit_policy_required';END IF;
  SELECT array_agg(value::uuid ORDER BY value::uuid) INTO ids FROM jsonb_array_elements_text(args->'record_ids');
  resource:=args->>'resource';cutoff:=(args->>'source_cutoff')::timestamptz;effective:=(args->>'effective_at')::timestamptz;expiry:=(args->>'expires_at')::timestamptz;
  IF cutoff IS NULL OR effective IS NULL OR expiry IS NULL OR NOT isfinite(cutoff) OR NOT isfinite(effective) OR NOT isfinite(expiry) OR cutoff>clock_timestamp() OR expiry<=clock_timestamp() OR expiry<=effective OR expiry>consent.expires_at THEN RAISE EXCEPTION 'financial_redaction_policy_time_invalid';END IF;
  SELECT jsonb_agg(item ORDER BY item->>'record_id' COLLATE "C") INTO plan FROM public.sandy_tenant_financial_redaction_plan(tenant,resource,ids,cutoff,false)item;
  before_sha:=public.sandy_tenant_financial_redaction_plan_sha(plan,resource,tenant,cutoff,manifest->>'manifest_sha256');
  INSERT INTO public.sandy_tenant_financial_redaction_policies(tenant_id,resource,record_ids,manifest_sha256,schema_sha256,source_sha256,consent_revision,source_cutoff,effective_at,expires_at,basis,policy_reference,created_by,source_admission_id) VALUES(tenant,resource,ids,manifest->>'manifest_sha256',manifest->>'schema_sha256',before_sha,consent.revision,cutoff,effective,expiry,args->>'basis',(args->>'policy_reference')::uuid,p_actor,p_admission) RETURNING * INTO policy;
  result:=public.sandy_tenant_financial_redaction_metadata(policy);
 ELSE
  SELECT * INTO policy FROM public.sandy_tenant_financial_redaction_policies WHERE id=(args->>'policy_id')::uuid AND tenant_id=tenant FOR UPDATE;
  IF policy.id IS NULL THEN RAISE EXCEPTION 'financial_redaction_policy_not_found';END IF;
  IF policy.manifest_sha256 IS DISTINCT FROM manifest->>'manifest_sha256' OR policy.schema_sha256 IS DISTINCT FROM manifest->>'schema_sha256' THEN RAISE EXCEPTION 'financial_redaction_policy_manifest_changed';END IF;
  result:=public.sandy_tenant_financial_redaction_metadata(policy);
  IF op='supabase.tenant.financial.redaction.policies.revoke' THEN
   IF args->>'confirm_policy_revocation' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'financial_redaction_revocation_confirmation_required';END IF;
   INSERT INTO public.sandy_tenant_financial_redaction_revocations(policy_id,actor_id,admission_id) VALUES(policy.id,p_actor,p_admission) ON CONFLICT(policy_id) DO NOTHING;
   result:=public.sandy_tenant_financial_redaction_metadata(policy);
  ELSIF op IN('supabase.tenant.financial.redaction.preview','supabase.tenant.financial.redaction.apply') THEN
   SELECT jsonb_agg(item ORDER BY item->>'record_id' COLLATE "C") INTO plan FROM public.sandy_tenant_financial_redaction_plan(tenant,policy.resource,policy.record_ids,policy.source_cutoff,op='supabase.tenant.financial.redaction.apply')item;
   before_sha:=public.sandy_tenant_financial_redaction_plan_sha(plan,policy.resource,tenant,policy.source_cutoff,manifest->>'manifest_sha256');
   changed:=(SELECT count(*) FROM jsonb_array_elements(plan) WHERE value->>'has_changes'='true');
   current_valid:=consent.revision=policy.consent_revision AND consent.allow_erasure IS TRUE;
   hold_blocked:=controls.legal_hold IS TRUE OR controls.retention_until>clock_timestamp();
   IF op='supabase.tenant.financial.redaction.preview' THEN result:=result||jsonb_build_object('current_sha256',before_sha,'source_changed',before_sha IS DISTINCT FROM policy.source_sha256,'changed_count',changed,'eligible',result->>'state'='active' AND current_valid AND NOT coalesce(hold_blocked,false) AND before_sha=policy.source_sha256,'hold_or_retention_blocked',coalesce(hold_blocked,false),'consent_current',current_valid);
   ELSE
    IF result->>'state' IS DISTINCT FROM 'active' OR current_valid IS DISTINCT FROM true OR hold_blocked IS TRUE OR args->>'confirm_text_redaction' IS DISTINCT FROM 'true' OR args->>'expected_current_sha256' IS DISTINCT FROM before_sha OR before_sha IS DISTINCT FROM policy.source_sha256 THEN RAISE EXCEPTION 'financial_redaction_current_policy_and_source_required';END IF;
    SELECT value INTO entry FROM jsonb_array_elements(manifest->'resources') WHERE value->>'table'=policy.resource;
    projection:='';FOR col IN SELECT value FROM jsonb_array_elements(entry->'columns') LOOP projection:=projection||CASE WHEN projection='' THEN '' ELSE ',' END||format('%L,t.%I',col->>'name',col->>'name');END LOOP;
    FOR row IN SELECT value FROM jsonb_array_elements(plan) WHERE value->>'has_changes'='true' ORDER BY value->>'record_id' COLLATE "C" LOOP
     INSERT INTO public.sandy_tenant_financial_redaction_leases(transaction_id,policy_id,admission_id,actor_id,canonical_arguments,tenant_id,resource,record_id,before_sha256,after_sha256) VALUES(pg_current_xact_id(),policy.id,p_admission,p_actor,p_canonical,tenant,policy.resource,(row->>'record_id')::uuid,row->>'before_sha256',row->>'after_sha256');
     sets:=CASE policy.resource WHEN 'sandy_commerce_accounts' THEN 'name=''[redacted:subject-data-request]''' WHEN 'sandy_commerce_entitlements' THEN 'reason=''[redacted:subject-data-request]''' WHEN 'sandy_commerce_invoices' THEN 'counterparty_name=''[redacted:subject-data-request]'',items=(SELECT jsonb_agg(jsonb_set(value,''{description}'',to_jsonb(''[redacted:subject-data-request]''::text)) ORDER BY ordinal) FROM jsonb_array_elements(t.items) WITH ORDINALITY e(value,ordinal))' ELSE 'description=''[redacted:subject-data-request]''' END;
     EXECUTE format('UPDATE public.%I t SET %s WHERE t.id=$1',policy.resource,sets) USING(row->>'record_id')::uuid;
     GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'financial_redaction_exact_record_update_required';END IF;
     EXECUTE format('SELECT encode(extensions.digest(jsonb_build_object(%s)::text,''sha256''),''hex'') FROM public.%I t WHERE t.id=$1',projection,policy.resource) INTO actual_sha USING(row->>'record_id')::uuid;
     IF actual_sha IS DISTINCT FROM row->>'after_sha256' THEN RAISE EXCEPTION 'financial_redaction_postcondition_failed';END IF;
     UPDATE public.sandy_tenant_financial_redaction_leases l SET used_at=coalesce(l.used_at,clock_timestamp()) WHERE l.transaction_id=pg_current_xact_id() AND l.resource=policy.resource AND l.record_id=(row->>'record_id')::uuid;
    END LOOP;
    SELECT jsonb_agg(item ORDER BY item->>'record_id' COLLATE "C") INTO after_plan FROM public.sandy_tenant_financial_redaction_plan(tenant,policy.resource,policy.record_ids,policy.source_cutoff,true)item;
    after_sha:=public.sandy_tenant_financial_redaction_plan_sha(after_plan,policy.resource,tenant,policy.source_cutoff,manifest->>'manifest_sha256');
    IF after_sha IS DISTINCT FROM public.sandy_tenant_financial_redaction_plan_sha(plan,policy.resource,tenant,policy.source_cutoff,manifest->>'manifest_sha256','after') OR EXISTS(SELECT 1 FROM public.sandy_tenant_financial_redaction_leases WHERE admission_id=p_admission AND used_at IS NULL) THEN RAISE EXCEPTION 'financial_redaction_complete_postcondition_required';END IF;
    INSERT INTO public.sandy_tenant_financial_redaction_applications(policy_id,admission_id,record_count,changed_count,before_sha256,after_sha256) VALUES(policy.id,p_admission,cardinality(policy.record_ids),changed,before_sha,after_sha);
    result:=public.sandy_tenant_financial_redaction_metadata(policy)||jsonb_build_object('before_sha256',before_sha,'after_sha256',after_sha,'changed_count',changed,'source_text_redacted',changed>0);
   END IF;
  END IF;
 END IF;
 INSERT INTO public.sandy_tenant_financial_redaction_receipts(admission_id,policy_id,result) VALUES(p_admission,policy.id,result);
 RETURN jsonb_build_object('ok',true,'result',result,'reused',false);
END $$;
REVOKE ALL ON FUNCTION public.sandy_tenant_lifecycle_operation_config(text),public.sandy_tenant_manifest_resolve(text),public.sandy_tenant_financial_redaction_metadata(public.sandy_tenant_financial_redaction_policies),public.sandy_tenant_financial_redaction_execute(uuid,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.sandy_tenant_financial_redaction_execute(uuid,uuid,text) TO service_role;
